          'M5 Ultra ahora escala oficialmente hasta 512 GB de memoria unificada en su configuración tope de Mac Studio, disponible a finales de octubre de 2026 a un precio que Apple no ha revelado pero que se espera muy por encima de $10.000 — ejecutará 70B FP16 sin pérdidas y modelos de la clase 120B+.',
