    leadAnswerBlock: '**분기점: 모델 크기 약 24GB. RTX 4090(1,008 GB/s)은 8B–24B 모델에서 더 빠릅니다. M5 Max(128GB 통합 메모리)는 이중 GPU 없이 70B 모델을 실행할 수 있는 유일한 소비자 옵션입니다. Apple의 2026년 8월 25일 업데이트로 보급형 Mac mini M6($899부터, 최대 32GB)가 추가되었고, Mac Studio M5 Ultra의 통합 메모리 상한이 512GB(최상위 구성, 2026년 10월 하순 출시)로 상향되었습니다. 3년 TCO: Mac Mini M5 Pro $1,804 대 RTX 4090 데스크탑 $3,682. 전력: Mac Mini $35/년 대 RTX 4090 $394/년(24/7 가동 기준).**',
